<?php
/** TEMP PS S1612 run e8d — D: deploy darbalaukis v3.11.1 (4 b64 dalys, md5 + token, gyvo failo sargas v3.11); T (naujas procesas): Klausimo „Siunta grįžta“ mygtukai per realius admin-post endpoint'us (nonce su sesija) — #35440 „Siųsti iš naujo“ + fiktyvus registras + cron sim „paėmė“; #35429 ir #35419 „Atšaukti — prekės grįžo į AV“ (blokas kai kita dalis išsiųsta, likučiai); dropship „Siųsti iš naujo“ #35441; gaudyklė prior. 4; Playwright Klausimai + Surinkti AV */
add_action('init', function(){
  if (!isset($_GET['ps_e8d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e8d'])); $o=array('v'=>'run e8d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
