    $E=function($k,$e,$t,$d,$pl=null){ return array('shipment_id'=>1,'pack_no'=>'','event'=>$e,'pack_status'=>$k,'pack_status_text'=>$t,'location'=>array('place'=>$pl,'address'=>null,'city'=>$pl,'lat'=>null,'lng'=>null),'date'=>$d,'date_iso'=>$d); };
    $cr=$E(0,'Shipment created','At sender','2026-09-04 09:00:00'); $at=$E(2,'At terminal','At terminal','2026-09-04 11:00:00','KAUNAS'); $ret=$E(7,'Returning to sender','Returning to sender','2026-09-04 14:00:00','KAUNAS');
