    $li=wp_generate_auth_cookie($uid,$exp,'logged_in',$tok); $_COOKIE[LOGGED_IN_COOKIE]=$li; wp_set_current_user($uid);
    $cs=array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>$li)));
    $veiksmas=function($v,$id) use ($cs){ $u=admin_url('admin-post.php?action=ps_dl_veiksmas&v='.$v.'&id='.$id.'&g='.rawurlencode(admin_url('admin.php?page=ps-desk')).'&_wpnonce='.wp_create_nonce('ps_dl_'.$v.'_'.$id)); $r=wp_remote_get($u,array('cookies'=>$cs,'timeout'=>90,'sslverify'=>false,'redirection'=>0)); if(is_wp_error($r)) return $r->get_error_message(); $loc=wp_remote_retrieve_header($r,'location'); parse_str((string)parse_url($loc,PHP_URL_QUERY),$q); return array('code'=>wp_remote_retrieve_response_code($r),'pd_ok'=>$q['pd_ok']??null,'pd_nr'=>$q['pd_nr']??mb_substr(wp_strip_all_tags(wp_remote_retrieve_body($r)),0,200)); };
    $bk=function($id){ $x=wc_get_order($id); if(!$x) return null; $reg=array(); foreach(Petshop_Siuntos::sarasas($id) as $s){ $reg[$s['sandelis']]=$s['numeriai']; } $eil=array(); foreach($x->get_items() as $it){ $eil[]=$it->get_product_id().' '.$it->get_meta('_ps_kelias').'/'.$it->get_meta('_ps_source').' r='.$it->get_meta('_ps_av_reduced_qty'); } return array('st'=>$x->get_status(),'iss'=>(string)$x->get_meta('_ps_dalys_issiusta'),'reg'=>$reg,'senos'=>Petshop_Darbalaukis::senos($x),'griz'=>array_keys(Petshop_Darbalaukis::grizta($x)),'surinkta'=>(string)$x->get_meta('_ps_surinkta'),'shipments'=>(string)$x->get_meta('_ps_shipments'),'type'=>(string)$x->get_meta('_ps_order_type'),'eil'=>$eil,'kl'=>array_map(function($s){ return $s['dalis'].' '.$s['busena'].' '.implode('/',$s['numeriai']); },Petshop_Darbalaukis::kliento_siuntos($x))); };
