    $x=wc_get_order($C); $reg=json_decode((string)$x->get_meta('_ps_siuntos'),true); $reg['av']=array('sandelis'=>'av','kodas'=>'001','manifest'=>'TEST-e8','numeriai'=>array('V07267E1000099'),'data'=>current_time('mysql')); $x->update_meta_data('_ps_siuntos',wp_json_encode($reg)); $x->update_meta_data('_ps_surinkta',current_time('mysql').'|testas'); $x->save();
    $o['1b_po_lipduko']=$bk($C);
    $SIM=array('V07267E1000099'=>array($cr,$at)); $o['1b_cron']=Petshop_Darbalaukis::venipak_sekimas(array($C)); $o['1b_po']=$bk($C); $o['1b_mail']=count(get_option('ps_e8_mail',array()));
    // 2. #35429 (completed, av 031/032, grynai AV, klientas svečias): sim 032 grįžta → Klausimas → „Atšaukti — prekės grįžo į AV“ → cancelled, variklis grąžina AV
    $A=35429; $pidA=reset(wc_get_order($A)->get_items())->get_product_id(); $o['2_stock_pries']=$stock($pidA);
    $SIM=array('V07267E1000032'=>array($cr,$at,$ret)); $o['2_cron']=Petshop_Darbalaukis::venipak_sekimas(array($A)); $o['2_pries']=$bk($A);
    $o['2_veiksmas']=$veiksmas('grizta_atsaukti',$A); $o['2_po']=$bk($A); $o['2_stock_po']=$stock($pidA);
    $o['2_notes']=array_map(function($n){ return mb_substr($n->content,0,200); },array_slice(wc_get_order_notes(array('order_id'=>$A,'limit'=>3)),0,3));
    // 3. #35419 (completed, vf 039 + ambrosia 040 dropship): vf grįžta → Atšaukti BLOKUOJAMAS (ambrosia išsiųsta); abi grįžta → Atšaukti → +q own stock abiem
    $B=35419; $its=wc_get_order($B)->get_items(); $pidsB=array(); foreach($its as $it){ $pidsB[$it->get_product_id()]=$it->get_meta('_ps_source'); } $o['3_pids']=$pidsB; foreach(array_keys($pidsB) as $pid){ $o['3_stock_pries'][$pid]=$stock($pid); }
    $SIM=array('V07267E1000039'=>array($cr,$at,$ret)); $o['3_cron']=Petshop_Darbalaukis::venipak_sekimas(array($B)); $o['3a_veiksmas']=$veiksmas('grizta_atsaukti',$B); $o['3a_po']=$bk($B);
    $SIM=array('V07267E1000040'=>array($cr,$at,$ret)); $o['3_cron2']=Petshop_Darbalaukis::venipak_sekimas(array($B)); $o['3b_veiksmas']=$veiksmas('grizta_atsaukti',$B); $o['3b_po']=$bk($B); foreach(array_keys($pidsB) as $pid){ $o['3_stock_po'][$pid]=$stock($pid); }
    // 4. dropship „Siųsti iš naujo“: #35441 (vf V…057) — statusas?
    $D=35441; $o['4_pries']=$bk($D); $pidD=reset(wc_get_order($D)->get_items())->get_product_id(); $o['4_stock_pries']=$stock($pidD);
    if(in_array(wc_get_order($D)->get_status(),array('processing','completed'),true)){ $SIM=array('V07267E1000057'=>array($cr,$at,$ret)); $o['4_cron']=Petshop_Darbalaukis::venipak_sekimas(array($D)); $o['4_veiksmas']=$veiksmas('grizta_is_naujo',$D); $o['4_po']=$bk($D); $o['4_stock_po']=$stock($pidD); $o['4_notes']=array_map(function($n){ return mb_substr($n->content,0,300); },array_slice(wc_get_order_notes(array('order_id'=>$D,'limit'=>2)),0,2)); }
    $o['laiskai']=array_map(function($m){ return $m['to'].' | '.$m['s'].' | '.$m['b']; },get_option('ps_e8_mail',array())); delete_option('ps_e8_mail'); $o['dev_zurnalas']=count((array)get_option('ps_dev_pastas_zurnalas',array()));
    $o['ivykiai']=$wpdb->get_results("SELECT uzsakymas, veiksmas, rezultatas, kanalas, kas_vardas, pastaba FROM {$p}ps_uzsakymu_ivykiai WHERE veiksmas LIKE 'grizta%' ORDER BY id DESC LIMIT 6",ARRAY_A);
    wp_set_current_user(0);
