    $o['shots']=array(array('n'=>'e8_klausimai','u'=>admin_url('admin.php?page=ps-desk&eile=klausimai'),'full'=>true,'eval'=>"({korteles:[...document.querySelectorAll('.dl-kortele')].map(x=>x.innerText.replace(/\\s+/g,' ').slice(0,120))})"),array('n'=>'e8_visi_35440','u'=>admin_url('admin.php?page=ps-desk&eile=visi&q=35440'),'w'=>1400,'full'=>false,'eval'=>"({eil:[...document.querySelectorAll('tr,.dl-eil')].map(x=>x.innerText.replace(/\\s+/g,' ')).filter(t=>t.includes('35440')).slice(0,2)})"));
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  $J($o);
